class Main {
    static int seed;
    static class Box {
        // 최초 사용 때 한 번 실행해요.
        static int total;
        static { total = Main.seed + 1; }
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Main.seed = n;
        // 처음 사용될 때 Box의 static 초기화가 실행돼요.
        Box a = new Box();
        Box b = new Box();
        System.out.println(a.total + " " + b.total);
    }
}
